use std::io::{self, Read};

trait Pricing {
    fn total(&self, qty: i128, unit: i128) -> i128;
}
struct Plain;
struct Bulk;
struct Member;

impl Pricing for Plain {
    fn total(&self, q: i128, u: i128) -> i128 {
        q * u
    }
}
impl Pricing for Bulk {
    fn total(&self, q: i128, u: i128) -> i128 {
        let t = q * u;
        if q >= 10 {
            t - t / 10
        } else {
            t
        }
    }
}
impl Pricing for Member {
    fn total(&self, q: i128, u: i128) -> i128 {
        let t = q * u;
        let mut r = t - t * 5 / 100;
        if q >= 3 {
            r -= 100;
        }
        r.max(0)
    }
}

fn main() {
    let mut s = String::new();
    io::stdin().read_to_string(&mut s).unwrap();
    let mut sum: i128 = 0;
    let mut out = String::new();
    for line in s.lines() {
        let p: Vec<&str> = line.split_whitespace().collect();
        if p.is_empty() {
            continue;
        }
        let name = p[0];
        let strat: Option<Box<dyn Pricing>> = match p.get(3).copied() {
            Some("plain") => Some(Box::new(Plain)),
            Some("bulk") => Some(Box::new(Bulk)),
            Some("member") => Some(Box::new(Member)),
            _ => None,
        };
        match strat {
            None => out.push_str(&format!("{} invalid kind\n", name)),
            Some(st) => {
                let q: i128 = p.get(1).and_then(|x| x.parse().ok()).unwrap_or(0);
                let u: i128 = p.get(2).and_then(|x| x.parse().ok()).unwrap_or(0);
                let t = st.total(q, u);
                sum += t;
                out.push_str(&format!("{} ${}.{:02}\n", name, t / 100, t % 100));
            }
        }
    }
    out.push_str(&format!("total ${}.{:02}\n", sum / 100, sum % 100));
    print!("{}", out);
}

